/*
 * Emit `src/api/schema.d.ts` from the pinned OpenAPI snapshot.
 *
 * The snapshot is `spec/openapi.json`. It is the contract `apiFetch` types
 * against; this script is the only writer of the generated file. `check:api`
 * reruns it into a temp file and diffs, so a hand-edit of the .d.ts fails CI.
 *
 * A URL in the generated file would fail `check:bundle` the moment dts
 * rollup copied it into `dist/index.d.ts`. The snapshot is already scrubbed
 * of schemes; this pass strips any that sneak back in.
 */

import { spawnSync } from 'node:child_process'
import { mkdtemp, readFile, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const pkg = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const spec = join(pkg, 'spec/openapi.json')
const dest = join(pkg, 'src/api/schema.d.ts')

const HEADER = `/**
 * Generated by scripts/generate-api-types.mjs from spec/openapi.json.
 * Do not edit. Run \`pnpm generate:api\` after refreshing the snapshot.
 */

`

const URL_RE = /(?:https?:)?\/\/[a-z0-9-]+(?:\.[a-z0-9-]+)+(?::\d+)?[^\s'"`)<>\\]*/gi

export async function generateApiTypes(out = dest) {
  const scratch = await mkdtemp(join(tmpdir(), 'navigator-ux-api-'))
  const raw = join(scratch, 'schema.d.ts')

  const result = spawnSync(
    'pnpm',
    ['exec', 'openapi-typescript', spec, '-o', raw],
    { cwd: pkg, encoding: 'utf8' },
  )
  if (result.status !== 0) {
    throw new Error(result.stderr || result.stdout || 'openapi-typescript failed')
  }

  let text = await readFile(raw, 'utf8')
  text = text.replace(/^\/\*\*[\s\S]*?\*\/\n/, '')
  text = text.replace(URL_RE, (url) => url.replace(/^(?:https?:)?\/\//, ''))
  await writeFile(out, HEADER + text)
  return out
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const out = await generateApiTypes()
  console.log(`generate-api-types: wrote ${out.slice(pkg.length + 1)}`)
}
